void kreb_GetRayCollisionSphere(float ray_position_x, float ray_position_y, float ray_position_z, float ray_direction_x, float ray_direction_y, float ray_direction_z, float center_x, float center_y, float center_z, float radius, float *kreb_out) {
    RayCollision kreb_value = GetRayCollisionSphere((Ray){{ray_position_x, ray_position_y, ray_position_z}, {ray_direction_x, ray_direction_y, ray_direction_z}}, (Vector3){center_x, center_y, center_z}, radius);
    kreb_out[0] = kreb_value.hit ? 1.0f : 0.0f;
    kreb_out[1] = kreb_value.distance;
    kreb_out[2] = kreb_value.point.x;
    kreb_out[3] = kreb_value.point.y;
    kreb_out[4] = kreb_value.point.z;
    kreb_out[5] = kreb_value.normal.x;
    kreb_out[6] = kreb_value.normal.y;
    kreb_out[7] = kreb_value.normal.z;
}

void kreb_GetRayCollisionBox(float ray_position_x, float ray_position_y, float ray_position_z, float ray_direction_x, float ray_direction_y, float ray_direction_z, float box_min_x, float box_min_y, float box_min_z, float box_max_x, float box_max_y, float box_max_z, float *kreb_out) {
    RayCollision kreb_value = GetRayCollisionBox((Ray){{ray_position_x, ray_position_y, ray_position_z}, {ray_direction_x, ray_direction_y, ray_direction_z}}, (BoundingBox){{box_min_x, box_min_y, box_min_z}, {box_max_x, box_max_y, box_max_z}});
    kreb_out[0] = kreb_value.hit ? 1.0f : 0.0f;
    kreb_out[1] = kreb_value.distance;
    kreb_out[2] = kreb_value.point.x;
    kreb_out[3] = kreb_value.point.y;
    kreb_out[4] = kreb_value.point.z;
    kreb_out[5] = kreb_value.normal.x;
    kreb_out[6] = kreb_value.normal.y;
    kreb_out[7] = kreb_value.normal.z;
}

void kreb_GetRayCollisionMesh(float ray_position_x, float ray_position_y, float ray_position_z, float ray_direction_x, float ray_direction_y, float ray_direction_z, void *mesh, const float *transform, float *kreb_out) {
    RayCollision kreb_value = GetRayCollisionMesh((Ray){{ray_position_x, ray_position_y, ray_position_z}, {ray_direction_x, ray_direction_y, ray_direction_z}}, *(Mesh *)mesh, kreb_matrix_from_floats(transform));
    kreb_out[0] = kreb_value.hit ? 1.0f : 0.0f;
    kreb_out[1] = kreb_value.distance;
    kreb_out[2] = kreb_value.point.x;
    kreb_out[3] = kreb_value.point.y;
    kreb_out[4] = kreb_value.point.z;
    kreb_out[5] = kreb_value.normal.x;
    kreb_out[6] = kreb_value.normal.y;
    kreb_out[7] = kreb_value.normal.z;
}

